// Package errors 提供 Typed Error Catalog
// 預定義結構化錯誤碼，讓 AI 與人都能一致理解和使用錯誤。
// 已定義的錯誤碼會寫進 manifest（.hyp/context.yaml）的 errors 區段，AI 讀 manifest 即知可用的錯誤碼。
//
// 保留範圍：E0xxx（通用）、E1xxx（驗證）、E2xxx（認證）為框架內建，c.BindInput 等直接回傳這些碼。
// 應用程式請使用其他碼（如 E4001 起、或 USER_001 這類帶前綴的碼），重複定義同一個碼會 panic
//
// @ai:generated by=claude-opus-4-6 date=2026-02-27
package errors

import (
	"fmt"
	"net/http"
	"sort"
	"sync"
)

// AppError 描述一個預定義的應用程式錯誤
// AppError 是不可變的定義，使用 With() 產生帶上下文的副本
type AppError struct {
	Code       string         `json:"code" yaml:"code"`
	HTTPStatus int            `json:"http_status" yaml:"http_status"`
	Message    string         `json:"message" yaml:"message"`
	Category   string         `json:"category" yaml:"category"`
	Details    map[string]any `json:"details,omitempty" yaml:"details,omitempty"`

	cause error // Wrap 附加的底層錯誤：只出現在 Error() 與 Unwrap()，不寫進回應
}

// Error 實作 error 介面（含 Wrap 的底層錯誤，供 log 使用）
func (e *AppError) Error() string {
	msg := fmt.Sprintf("[%s] %s", e.Code, e.Message)
	if len(e.Details) > 0 {
		msg += fmt.Sprintf(" %v", e.Details)
	}
	if e.cause != nil {
		msg += ": " + e.cause.Error()
	}
	return msg
}

// Wrap 產生附帶底層錯誤的副本（原 AppError 不變）。底層錯誤供 errors.Is / errors.As 與 log 使用，
// 不寫進 JSON 回應，避免內部訊息洩漏給客戶端。
// 先前只能 With("err", err)：error 值序列化成 JSON 是 {}，回應裡只剩 "err":{}
func (e *AppError) Wrap(cause error) *AppError {
	cp := e.clone()
	cp.cause = cause
	return cp
}

// Unwrap 回傳 Wrap 附加的底層錯誤
func (e *AppError) Unwrap() error {
	return e.cause
}

// With 產生帶上下文細節的副本（原 AppError 不變）
func (e *AppError) With(key string, value any) *AppError {
	cp := e.clone()
	if cp.Details == nil {
		cp.Details = make(map[string]any)
	}
	cp.Details[key] = value
	return cp
}

// WithDetail 同 With，語義更明確
func (e *AppError) WithDetail(key string, value any) *AppError {
	return e.With(key, value)
}

// WithDetails 一次附加多個 key-value
func (e *AppError) WithDetails(kvs map[string]any) *AppError {
	cp := e.clone()
	if cp.Details == nil {
		cp.Details = make(map[string]any)
	}
	for k, v := range kvs {
		cp.Details[k] = v
	}
	return cp
}

// WithMessage 覆蓋預設訊息
func (e *AppError) WithMessage(msg string) *AppError {
	cp := e.clone()
	cp.Message = msg
	return cp
}

// Is 判斷是否為同一錯誤碼（忽略 Details）
func (e *AppError) Is(target error) bool {
	t, ok := target.(*AppError)
	if !ok {
		return false
	}
	return e.Code == t.Code
}

// JSON 回傳適合做 HTTP response 的結構
func (e *AppError) JSON() map[string]any {
	result := map[string]any{
		"code":    e.Code,
		"message": e.Message,
	}
	if len(e.Details) > 0 {
		result["details"] = e.Details
	}
	return result
}

// clone 建立淺拷貝
func (e *AppError) clone() *AppError {
	cp := *e
	if e.Details != nil {
		cp.Details = make(map[string]any, len(e.Details))
		for k, v := range e.Details {
			cp.Details[k] = v
		}
	}
	return &cp
}

// --- 全域 Catalog ---

// Catalog 儲存所有已定義的 AppError
type Catalog struct {
	mu     sync.RWMutex
	errors map[string]*AppError // code → error
}

var globalCatalog = &Catalog{
	errors: make(map[string]*AppError),
}

// Define 定義並註冊一個新的 AppError
// 通常在 package-level var 區塊中使用。以下屬於程式啟動期的設定錯誤，直接 panic：
//   - 同一個錯誤碼重複定義：先前靜默覆蓋 catalog，同一個碼在 catalog 與原變數中意義不同
//     （例如應用程式定義 E1001 = User not found，c.BindInput 驗證失敗回的也是 E1001）
//   - HTTP 狀態碼不在 100–599：先前狀態碼 0 的錯誤實際以 200 送出
func Define(code string, httpStatus int, message, category string) *AppError {
	if httpStatus < 100 || httpStatus > 599 {
		panic(fmt.Sprintf("errors: Define(%q): invalid HTTP status %d", code, httpStatus))
	}
	e := &AppError{
		Code:       code,
		HTTPStatus: httpStatus,
		Message:    message,
		Category:   category,
	}
	globalCatalog.register(e)
	return e
}

// register 內部註冊方法；錯誤碼已存在時 panic（見 Define）
func (c *Catalog) register(e *AppError) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if old, ok := c.errors[e.Code]; ok {
		panic(fmt.Sprintf("errors: code %q already defined (%q, category %q); E0xxx–E2xxx are reserved for HypGo",
			e.Code, old.Message, old.Category))
	}
	c.errors[e.Code] = e
}

// GlobalCatalog 返回全域 Catalog
func GlobalCatalog() *Catalog {
	return globalCatalog
}

// All 返回所有已定義的錯誤，依錯誤碼排序（manifest 據此輸出，順序固定才不會每次啟動都改寫）
func (c *Catalog) All() []*AppError {
	c.mu.RLock()
	defer c.mu.RUnlock()

	result := make([]*AppError, 0, len(c.errors))
	for _, e := range c.errors {
		result = append(result, e)
	}
	sort.Slice(result, func(i, j int) bool { return result[i].Code < result[j].Code })
	return result
}

// Get 根據 code 查詢錯誤
func (c *Catalog) Get(code string) (*AppError, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	e, ok := c.errors[code]
	return e, ok
}

// ByCategory 根據分類查詢
func (c *Catalog) ByCategory(category string) []*AppError {
	c.mu.RLock()
	defer c.mu.RUnlock()

	var result []*AppError
	for _, e := range c.errors {
		if e.Category == category {
			result = append(result, e)
		}
	}
	return result
}

// Len 返回已定義的錯誤數量
func (c *Catalog) Len() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return len(c.errors)
}

// Reset 清空（測試用）
func (c *Catalog) Reset() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.errors = make(map[string]*AppError)
}

// --- 常用預定義錯誤 ---

var (
	// 通用
	ErrNotFound         = Define("E0001", http.StatusNotFound, "Resource not found", "general")
	ErrBadRequest       = Define("E0002", http.StatusBadRequest, "Bad request", "general")
	ErrInternalError    = Define("E0003", http.StatusInternalServerError, "Internal server error", "general")
	ErrMethodNotAllowed = Define("E0004", http.StatusMethodNotAllowed, "Method not allowed", "general")

	// 驗證
	ErrValidationFailed = Define("E1001", http.StatusUnprocessableEntity, "Validation failed", "validation")
	ErrMissingField     = Define("E1002", http.StatusBadRequest, "Missing required field", "validation")
	ErrInvalidFormat    = Define("E1003", http.StatusBadRequest, "Invalid format", "validation")

	// 認證
	ErrUnauthorized = Define("E2001", http.StatusUnauthorized, "Authentication required", "auth")
	ErrForbidden    = Define("E2002", http.StatusForbidden, "Permission denied", "auth")
	ErrTokenExpired = Define("E2003", http.StatusUnauthorized, "Token expired", "auth")
)
